71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /**
75	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
76	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
77	     */
78	    /**
79	     * Dedicated audit logger. Successful side-effects (e.g. owner creation) are recorded here so
80	     * they can be routed and asserted independently of the application's diagnostic logging.
81	     */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    /**
85	     * Dedicated notification logger. A welcome notification is enqueued here on a successful owner
86	     * create, so downstream notification delivery can be routed and asserted independently of the
87	     * application's diagnostic and audit logging.
88	     */
89	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
90	
91	    private static final Pattern EMAIL_PATTERN =
92	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
93	
94	    /**
95	     * Disposable email domains that are refused: an owner whose email domain is on this blocklist
96	     * is rejected. The value is the already-normalized (trimmed, lower-cased) email's domain.
97	     */
98	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
99	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
100	
101	    /**
102	     * Common address abbreviations expanded to their full form during address normalization.
103	     * Matching is performed per whitespace-separated token on the upper-cased value.
104	     */
105	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
106	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
107	
108	    /**
109	     * Required national-number length (the digits after the country code) per E.164 country code.
110	     * A number whose country code appears here must carry exactly the mapped number of national
111	     * digits; country codes not listed fall back to the generic 8-to-15 total-digit rule.
112	     */
113	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
114	        Map.of("61", 9, "1", 10);
115	
116	    /**
117	     * Inclusive 4-digit postcode range {@code {low, high}} per region, the fixed ground truth for
118	     * validating an owner's postcode against the region derived from its city. A region not listed
119	     * here (e.g. the {@code "UNKNOWN"} locality of an unmapped city) imposes no range constraint, so
120	     * any 4-digit postcode is accepted.
121	     */
122	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
123	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
124	
125	    /**
126	     * City -> canonical region, the fixed ground truth for deriving the region a postcode is
127	     * validated against. A city not listed here derives the {@code "UNKNOWN"} region, which imposes
128	     * no postcode-range constraint.
129	     */
130	    private static final Map<String, String> CITY_REGION = Map.of(
131	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
132	
133	    /**
134	     * The HTTP header carrying a client-supplied idempotency token for owner creation. When a create
135	     * repeats with a token already seen, the originally created owner is returned rather than a
136	     * duplicate being made.
137	     */
138	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
139	
140	    /**
141	     * Maps each seen {@code Idempotency-Key} to the id of the owner its first successful create
142	     * produced, so a repeat with the same key returns that owner instead of creating a duplicate.
143	     */
144	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
145	
146	    /**
147	     * Source of the {@code seq} field on the structured {@code OWNER_CREATED} audit event: a
148	     * monotonically increasing integer stamped on each owner create, across all creates.
149	     */
150	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
151	
