170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
173	        Collection<Owner> owners;
174	        if (lastName != null) {
175	            owners = this.clinicService.findOwnerByLastName(lastName);
176	        } else {
177	            owners = this.clinicService.findAllOwners();
178	        }
179	        if (owners.isEmpty()) {
180	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
181	        }
182	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
183	    }
