185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
188	        Owner owner = this.clinicService.findOwnerById(ownerId);
189	        if (owner == null) {
190	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	        }
192	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
198	        HttpHeaders headers = new HttpHeaders();
199	        String idempotencyKey = currentIdempotencyKey();
200	        if (idempotencyKey != null) {
201	            Integer existingId = idempotentCreates.get(idempotencyKey);
202	            if (existingId != null) {
203	                Owner existing = this.clinicService.findOwnerById(existingId);
204	                if (existing != null) {
205	                    // Repeat of a create already performed under this key: return the original
206	                    // owner with 200 instead of creating a duplicate.
207	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
208	                }
209	            }
210	        }
211	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
212	        LocalDate suppliedDate = owner.getRegistrationDate();
213	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
214	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
215	                "The registration date must not be in the future");
216	        }
217	        LocalDate effectiveDate = suppliedDate != null ? suppliedDate : LocalDate.now();
218	        LocalDate registrationDate = toBusinessDay(effectiveDate);
219	        owner.setRegistrationDate(registrationDate);
220	        long createdToday = this.clinicService.findAllOwners().stream()
221	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
222	            .count();
223	        if (createdToday >= 100) {
224	            throw new RestRejectionException(HttpStatus.TOO_MANY_REQUESTS,
225	                "The daily owner registration limit has been reached");
226	        }
227	        owner.setBulkSignupWarning(createdToday > 80);
228	        if (!applyAddress(owner)) {
229	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
230	                "A valid address is required");
231	        }
232	        String telephone = toE164(owner.getTelephone());
233	        if (telephone == null) {
234	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
235	                "The telephone number is not a valid E.164 number");
236	        }
237	        owner.setTelephone(telephone);
238	        if (owner.getEmail() != null) {
239	            String email = normalizeEmail(owner.getEmail());
240	            if (!EMAIL_PATTERN.matcher(email).matches()) {
241	                throw new RestRejectionException(HttpStatus.BAD_REQUEST,
242	                    "The email address is not valid");
243	            }
244	            if (isDisposableEmailDomain(email)) {
245	                throw new RestRejectionException(HttpStatus.BAD_REQUEST,
246	                    "The email domain is not accepted");
247	            }
248	            owner.setEmail(email);
249	        }
250	        if (!isPostcodeValidForCity(owner.getPostcode(), regionForCity(owner.getCity()))) {
251	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
252	                "The postcode is not valid for the owner's city region");
253	        }
254	        String cityKey = householdKey(owner.getCity());
255	        long cityCount = this.clinicService.findAllOwners().stream()
256	            .filter(existing -> existing.getCity() != null
257	                && cityKey.equals(householdKey(existing.getCity())))
258	            .count();
259	        if (cityCount >= 50) {
260	            throw new RestRejectionException(HttpStatus.CONFLICT,
261	                "The city has reached its owner capacity");
262	        }
263	        // Approaching-capacity warning: the city already holds 40-49 owners, just short of the
264	        // hard limit of 50. The 50+ rejection above still applies unchanged.
265	        owner.setCapacityWarning(cityCount >= 40 && cityCount < 50);
266	        // The household is keyed on (normalized last name, postcode): every owner derives the same
267	        // deterministic householdId from those two fields, so owners sharing them are the same
268	        // household. This computed id is what duplicate detection and the household size below key off.
269	        String householdId = householdId(owner);
270	        owner.setHouseholdId(householdId);
271	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
272	            .filter(existing -> !existing.getDeleted())
273	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
274	            .toList();
275	        owner.setHouseholdSize(householdMembers.size() + 1);
276	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
277	        // Duplicate detection is now the single identityKey (below): the separate household-duplicate
278	        // 409 block from the computed householdId no longer applies. Two owners sharing a last name and
279	        // postcode but with different telephones therefore have different identity keys and are admitted
280	        // as a soft match rather than rejected. The householdId and householdSize computed above still
281	        // drive household sizing and the level ceiling below.
282	        // Level ceiling: an owner admitted into an already-populated household without declaring
283	        // membership has its membership level capped at one above the household's current maximum, so
284	        // an undeclared newcomer can never outrank the household it joined. Declared members and
285	        // household founders are left uncapped. With no existing household member no cap applies.
286	        if (!householdMembers.isEmpty() && !sharesHousehold) {
287	            int maxHouseholdLevel = householdMembers.stream()
288	                .mapToInt(Owner::getMembershipLevel)
289	                .max()
290	                .orElse(0);
291	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
292	        }
293	        // Single consolidated duplicate check: the telephone, email and household duplicate rules are
294	        // all expressed through the one derived identityKey (telephone|email|householdId). A create is
295	        // rejected only when a new owner's WHOLE identityKey equals an existing owner's; because the
296	        // telephone is part of the key, two household members with different telephones are allowed.
297	        // This still catches a full identity repeat even when it declares sharesHousehold.
298	        String identityKey = owner.getIdentityKey();
299	        boolean identityInUse = this.clinicService.findAllOwners().stream()
300	            .filter(existing -> !existing.getDeleted())
301	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
302	        if (identityInUse) {
303	            throw new RestRejectionException(HttpStatus.CONFLICT,
304	                "An owner with the same identity already exists");
305	        }
306	        // Soft-duplicate detection. A declared household member (sharesHousehold) is never a suspected
307	        // duplicate. Any other owner whose identityKey differs from an existing owner's but that shares
308	        // that owner's Soundex(last name) and postcode is flagged as a possible duplicate of the
309	        // earliest such owner. A full identity match would already have been rejected as a 409 above,
310	        // so every existing owner reaching here necessarily has a different identityKey.
311	        if (sharesHousehold) {
312	            owner.setPossibleDuplicate(false);
313	        } else {
314	            String softDuplicateLastNameSoundex = Owner.soundex(owner.getLastName());
315	            String softDuplicatePostcode = owner.getPostcode();
316	            Owner possibleDuplicate = softDuplicatePostcode == null ? null
317	                : this.clinicService.findAllOwners().stream()
318	                    .filter(existing -> !existing.getDeleted())
319	                    .filter(existing -> softDuplicateLastNameSoundex.equals(Owner.soundex(existing.getLastName())))
320	                    .filter(existing -> softDuplicatePostcode.equals(existing.getPostcode()))
321	                    .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
322	                    .min(Comparator.comparing(Owner::getId))
323	                    .orElse(null);
324	            if (possibleDuplicate != null) {
325	                owner.setPossibleDuplicate(true);
326	                owner.setPossibleDuplicateOf(possibleDuplicate.getId());
327	            } else {
328	                owner.setPossibleDuplicate(false);
329	            }
330	        }
331	        owner.setMemberId(memberId(owner));
332	        String firstNameKey = householdKey(owner.getFirstName());
333	        String namesakeLastNameKey = householdKey(owner.getLastName());
334	        long namesakeCount = this.clinicService.findAllOwners().stream()
335	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
336	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
337	            .count();
338	        owner.setNamesakeCount((int) namesakeCount);
339	        this.clinicService.saveOwner(owner);
340	        if (idempotencyKey != null) {
341	            idempotentCreates.put(idempotencyKey, owner.getId());
342	        }
343	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
344	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
345	            owner.getMembershipLevel());
346	        OwnerCreatedEvent event = new OwnerCreatedEvent(OWNER_CREATED_SEQUENCE.incrementAndGet(),
347	            owner.getId(), primaryIdentifier(owner), owner.getMembershipLevel(),
348	            owner.getOwnerSegment());
349	        AUDIT.info("{}", event.toJson());
350	        // Enqueue a welcome notification for the freshly created owner, carrying the owner id and
351	        // the member id so downstream delivery can address and personalize it.
352	        NOTIFY.info("welcome ownerId={} memberId={}", owner.getId(), owner.getMemberId());
353	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
354	        headers.setLocation(UriComponentsBuilder.newInstance()
355	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
356	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
357	    }
358	
359	    /**
360	     * Validates an owner's postcode against the region derived from its city. The postcode is
361	     * optional: a {@code null} value is always accepted. When present it must fall within the
362	     * inclusive range mapped to the region by {@link #REGION_POSTCODES}; a region with no known
363	     * range (e.g. the {@code "UNKNOWN"} locality of an unmapped city) accepts any 4-digit postcode.
364	     * The 4-digit syntax itself is enforced upstream by bean validation.
365	     *
366	     * @param postcode the owner's postcode (may be {@code null})
367	     * @param locality the region derived from the owner's city
368	     * @return {@code true} when the postcode is absent, the region has no range, or the postcode is
369	     *         within the region's range; {@code false} when it is out of range
370	     */
371	    /**
372	     * The canonical region for the given city via the fixed {@link #CITY_REGION} table, or
373	     * {@code "UNKNOWN"} when the city is {@code null} or not in the table.
374	     *
375	     * @param city the owner's city (may be {@code null})
376	     * @return the canonical region, or {@code "UNKNOWN"}
377	     */
378	    /**
379	     * The {@code Idempotency-Key} header of the current request, trimmed, or {@code null} when the
380	     * header is absent, blank, or no servlet request is bound to the current thread.
381	     *
382	     * @return the idempotency key, or {@code null}
383	     */
384	    private String currentIdempotencyKey() {
385	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
386	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
387	            String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
388	            if (key != null && !key.isBlank()) {
389	                return key.trim();
390	            }
391	        }
392	        return null;
393	    }
394	
395	    private String regionForCity(String city) {
396	        if (city == null) {
397	            return "UNKNOWN";
398	        }
399	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
400	    }
401	
402	    private boolean isPostcodeValidForCity(String postcode, String locality) {
403	        if (postcode == null) {
404	            return true;
405	        }
406	        int[] range = REGION_POSTCODES.get(locality);
407	        if (range == null) {
408	            return true;
409	        }
410	        int value = Integer.parseInt(postcode);
411	        return value >= range[0] && value <= range[1];
412	    }
413	
414	    /**
415	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
416	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
417	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
418	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. For
419	     * recognised country codes the national number (the digits after the country code) must also be
420	     * exactly the length that country requires ({@code '+61'} needs 9 national digits, {@code '+1'}
421	     * needs 10); a wrong national-number length yields {@code null}.
422	     *
423	     * @param telephone the raw telephone value (may be {@code null})
424	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
425	     *         a valid E.164 number
426	     */
427	    private String toE164(String telephone) {
428	        if (telephone == null) {
429	            return null;
430	        }
431	        String trimmed = telephone.trim();
432	        boolean hasCountryCode = trimmed.startsWith("+");
433	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
434	        if (hasCountryCode) {
435	            cleaned = cleaned.substring(1);
436	        }
437	        if (!cleaned.matches("[0-9]+")) {
438	            return null;
439	        }
440	        String digits;
441	        if (hasCountryCode) {
442	            digits = cleaned;
443	        } else {
444	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
445	            digits = "61" + national;
446	        }
447	        if (digits.length() < 8 || digits.length() > 15) {
448	            return null;
449	        }
450	        if (!hasValidNationalNumberLength(digits)) {
451	            return null;
452	        }
453	        return "+" + digits;
454	    }
455	
456	    /**
457	     * Checks the national-number length of an E.164 digit string (country code plus national
458	     * number, without the leading {@code '+'}) against its country code. When the number's country
459	     * code is one of the {@link #NATIONAL_NUMBER_LENGTHS recognised codes}, the digits after the
460	     * country code must number exactly what that country requires; the longest matching country
461	     * code wins. Numbers whose country code is not recognised are accepted here (they are governed
462	     * only by the generic total-length rule).
463	     *
464	     * @param digits the E.164 digits without the leading {@code '+'} (e.g. {@code "61412345678"})
465	     * @return {@code true} if the national-number length is acceptable for the country code
466	     */
467	    private boolean hasValidNationalNumberLength(String digits) {
468	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
469	            .filter(entry -> digits.startsWith(entry.getKey()))
470	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
471	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
472	            .orElse(true);
473	    }
474	
475	    /**
476	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
477	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
478	     *
479	     * @param email the raw email value (must not be {@code null})
480	     * @return the trimmed, lower-cased email
481	     */
482	    private String normalizeEmail(String email) {
483	        return email.trim().toLowerCase(Locale.ROOT);
484	    }
485	
486	    /**
487	     * Whether the domain of the given normalized email is on the disposable-domain blocklist
488	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The domain is the substring after the last {@code '@'};
489	     * an email without an {@code '@'} carries no blocked domain.
490	     *
491	     * @param email the trimmed, lower-cased email
492	     * @return {@code true} when the email's domain is blocklisted
493	     */
494	    private boolean isDisposableEmailDomain(String email) {
495	        int at = email.lastIndexOf('@');
496	        if (at < 0) {
497	            return false;
498	        }
499	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
500	    }
501	
502	    /**
503	     * Applies the owner's address, preferring the structured form over the flat one. When a
504	     * non-blank {@code addressLine1} is supplied the structured fields are normalized in place and
505	     * the flat {@code address} is composed as the normalized {@code addressLine1} followed, when a
506	     * non-blank {@code addressLine2} is present, by a single space and the normalized
507	     * {@code addressLine2}. Otherwise the flat {@code address} is normalized in place. An owner
508	     * that supplies neither a non-blank {@code addressLine1} nor a non-blank flat {@code address}
509	     * is invalid.
510	     *
511	     * @param owner the owner whose address fields are normalized and composed in place
512	     * @return {@code true} when a usable address was applied, {@code false} when none was supplied
513	     */
514	    private boolean applyAddress(Owner owner) {
515	        String line1 = owner.getAddressLine1();
516	        if (line1 != null && !line1.isBlank()) {
517	            String normalizedLine1 = normalizeAddress(line1);
518	            owner.setAddressLine1(normalizedLine1);
519	            String composed = normalizedLine1;
520	            String line2 = owner.getAddressLine2();
521	            if (line2 != null && !line2.isBlank()) {
522	                String normalizedLine2 = normalizeAddress(line2);
523	                owner.setAddressLine2(normalizedLine2);
524	                composed = normalizedLine1 + " " + normalizedLine2;
525	            }
526	            owner.setAddress(composed);
527	            return true;
528	        }
529	        String address = normalizeAddress(owner.getAddress());
530	        if (address == null || address.isEmpty()) {
531	            return false;
532	        }
533	        owner.setAddress(address);
534	        return true;
535	    }
