537	    /**
538	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
539	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
540	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
541	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
542	     * normalized form, and every household comparison uses it.
543	     *
544	     * @param address the raw address value (may be {@code null})
545	     * @return the normalized address, or {@code null} if the input was {@code null}
546	     */
547	    private String normalizeAddress(String address) {
548	        if (address == null) {
549	            return null;
550	        }
551	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
552	        if (collapsed.isEmpty()) {
553	            return collapsed;
554	        }
555	        String[] tokens = collapsed.split(" ");
556	        StringBuilder sb = new StringBuilder(collapsed.length());
557	        for (int i = 0; i < tokens.length; i++) {
558	            if (i > 0) {
559	                sb.append(' ');
560	            }
561	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
562	        }
563	        return sb.toString();
564	    }
565	
566	    /**
567	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
568	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
569	     * so that owners are compared case-insensitively with collapsed whitespace.
570	     *
571	     * @param value the raw value (must not be {@code null})
572	     * @return the normalized comparison key
573	     */
574	    private String householdKey(String value) {
575	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
576	    }
577	
578	    /**
579	     * Derives a stable, shared household identifier for the owner's household: the first 12 hex
580	     * characters of the SHA-256 digest of
581	     * {@code normalizedLastName + '|' + postcode + '|' + "V2"}, where the last name is normalized
582	     * with {@link #householdKey}, an absent postcode is rendered as the empty string and {@code "V2"}
583	     * is the fixed {@link Owner#IDENTITY_VERSION_TAG version tag} that rederives the identifier under
584	     * version 2 so it differs from every version-1 value. Because it is a pure function of the last
585	     * name and postcode, every owner sharing those two fields derives the identical identifier and
586	     * therefore belongs to the same household.
587	     *
588	     * @param owner the owner whose household identifier is derived
589	     * @return the stable household identifier
590	     */
591	    private String householdId(Owner owner) {
592	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
593	        String key = householdKey(owner.getLastName()) + "|" + postcode
594	            + "|" + Owner.IDENTITY_VERSION_TAG;
595	        try {
596	            byte[] digest = MessageDigest.getInstance("SHA-256")
597	                .digest(key.getBytes(StandardCharsets.UTF_8));
598	            StringBuilder sb = new StringBuilder(digest.length * 2);
599	            for (byte b : digest) {
600	                sb.append(String.format("%02x", b));
601	            }
602	            return sb.substring(0, 12);
603	        }
604	        catch (java.security.NoSuchAlgorithmException e) {
605	            throw new IllegalStateException("SHA-256 not available", e);
606	        }
607	    }
