621	    /**
622	     * Immutable structured audit event emitted alongside the human-readable audit line when an owner
623	     * is created. It is serialized to a compact JSON object and published to the {@code AUDIT}
624	     * logger so it can be routed and asserted independently of the diagnostic log. The
625	     * {@code memberId} field carries the owner's {@link #primaryIdentifier(Owner) current primary
626	     * identifier}, the version-2 member id, and {@code ownerSegment} carries the owner segment
627	     * recomputed from the version-2 identity. The event is at schema version 2, stamped by the
628	     * {@code schemaVersion} field.
629	     */
630	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
631	                                     Integer membershipLevel, String ownerSegment) {
632	
633	        private static final String EVENT = "OWNER_CREATED";
634	
635	        private static final int SCHEMA_VERSION = 2;
636	
637	        private String toJson() {
638	            return "{\"seq\":" + this.seq
639	                + ",\"schemaVersion\":" + SCHEMA_VERSION
640	                + ",\"ownerId\":" + this.ownerId
641	                + ",\"memberId\":" + quote(this.memberId)
642	                + ",\"membershipLevel\":" + this.membershipLevel
643	                + ",\"ownerSegment\":" + quote(this.ownerSegment)
644	                + ",\"event\":\"" + EVENT + "\"}";
645	        }
