647	        private static String quote(String value) {
648	            if (value == null) {
649	                return "null";
650	            }
651	            String escaped = value.replace("\\", "\\\\").replace("\"", "\\\"");
652	            return "\"" + escaped + "\"";
653	        }
654	    }
