656	    /**
657	     * Builds the member id for a newly registered owner in the form
658	     * {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION} is the version-2 region code
659	     * ({@link Owner#getIdentityRegionCode()}: the plain region derivation shared with
660	     * {@link Owner#getLocality() locality} — postcode range first, falling back to the city, or
661	     * {@code 'UNKNOWN'} — with the fixed {@code 'V2'} version tag mixed in); {@code FY} is the
662	     * 2-digit fiscal year of the registration date (the last two digits of
663	     * {@link Owner#getFiscalYear()}); {@code HASH8} is the first 8 upper-case hex characters of the
664	     * SHA-256 digest of the normalized telephone concatenated with the last name (the same HASH8
665	     * used by the region-and-hash identity); and {@code CHK} is a single Luhn check digit computed
666	     * over the decimal digits of {@code <REGION><FY><HASH8>} (e.g. {@code 'NSWV2261A2B3C4D7'}). When
667	     * the computed id collides with
668	     * an existing owner's member id, {@code '-<n>'} is appended using the smallest {@code n} of 2 or
669	     * more that makes the result unique, guaranteeing distinct owners always receive distinct member
670	     * ids.
671	     *
672	     * @param owner the owner whose member id is derived (with normalized telephone and registration
673	     *              date already set)
674	     * @return the assigned member id
675	     */
676	    private String memberId(Owner owner) {
677	        String region = owner.getIdentityRegionCode();
678	        String fiscalYear = owner.getFiscalYear();
679	        String fy = fiscalYear == null ? "00" : fiscalYear.substring(fiscalYear.length() - 2);
680	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName(), 8);
681	        String core = region + fy + hash8;
682	        String base = core + luhnCheckDigit(core);
683	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
684	            .map(Owner::getMemberId)
685	            .filter(id -> id != null)
686	            .collect(Collectors.toSet());
687	        if (!existingIds.contains(base)) {
688	            return base;
689	        }
690	        int n = 2;
691	        while (existingIds.contains(base + "-" + n)) {
692	            n++;
693	        }
694	        return base + "-" + n;
695	    }
696	
697	    /**
698	     * The single Luhn check digit ({@code 0}-{@code 9}) computed with the standard Luhn algorithm
699	     * over the decimal digits contained in {@code value} (non-digit characters are ignored).
700	     *
701	     * @param value the string whose decimal digits are checked
702	     * @return the Luhn check digit
703	     */
704	    private static int luhnCheckDigit(String value) {
705	        int sum = 0;
706	        boolean dbl = true;
707	        for (int i = value.length() - 1; i >= 0; i--) {
708	            char c = value.charAt(i);
709	            if (c < '0' || c > '9') {
710	                continue;
711	            }
712	            int d = c - '0';
713	            if (dbl) {
714	                d *= 2;
715	                if (d > 9) {
716	                    d -= 9;
717	                }
718	            }
719	            sum += d;
720	            dbl = !dbl;
721	        }
722	        return (10 - (sum % 10)) % 10;
723	    }
724	
725	    /**
726	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
727	     * UTF-8 bytes of {@code input}.
728	     *
729	     * @param input  the value to hash
730	     * @param length the number of leading hex characters to keep
731	     * @return the truncated, upper-cased hex digest
732	     */
733	    private String sha256UpperHex(String input, int length) {
734	        try {
735	            byte[] digest = MessageDigest.getInstance("SHA-256")
736	                .digest(input.getBytes(StandardCharsets.UTF_8));
737	            StringBuilder sb = new StringBuilder(digest.length * 2);
738	            for (byte b : digest) {
739	                sb.append(String.format("%02x", b));
740	            }
741	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
742	        }
743	        catch (java.security.NoSuchAlgorithmException e) {
744	            throw new IllegalStateException("SHA-256 not available", e);
745	        }
746	    }
