748	    /** Fixed public holidays that the business-day roll skips. */
749	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
750	        LocalDate.parse("2026-01-01"),
751	        LocalDate.parse("2026-01-26"),
752	        LocalDate.parse("2026-04-25"),
753	        LocalDate.parse("2026-12-25"),
754	        LocalDate.parse("2026-12-28"));
755	
756	    /**
757	     * Rolls a registration date forward onto a business day. When the given date falls on a
758	     * Saturday, Sunday or a listed public holiday it is advanced one day at a time until it
759	     * lands on a non-holiday weekday; a business day is returned unchanged.
760	     *
761	     * @param date the effective registration date (must not be {@code null})
762	     * @return the same date if it is already a business day, otherwise the next business day
763	     */
764	    private LocalDate toBusinessDay(LocalDate date) {
765	        while (isNonBusinessDay(date)) {
766	            date = date.plusDays(1);
767	        }
768	        return date;
769	    }
770	
771	    private boolean isNonBusinessDay(LocalDate date) {
772	        DayOfWeek dayOfWeek = date.getDayOfWeek();
773	        return dayOfWeek == DayOfWeek.SATURDAY
774	            || dayOfWeek == DayOfWeek.SUNDAY
775	            || PUBLIC_HOLIDAYS.contains(date);
776	    }
