41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	
57	    /**
58	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
59	     * class.
60	     *
61	     * @param e     Object referring to the thrown exception.
62	     * @param status HTTP response status.
63	     * @param url URL request.
64	     */
65	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
66	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
67	        problemDetail.setType(URI.create(url.toString()));
68	        problemDetail.setTitle(e.getClass().getSimpleName());
69	        problemDetail.setDetail(detail);
70	        problemDetail.setProperty("timestamp", Instant.now());
71	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
72	        return problemDetail;
73	    }
74	
75	    /**
76	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
77	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
78	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
79	     * would catch it and report an authorization failure as a 500.
80	     *
81	     * @param e The {@link AccessDeniedException} to propagate
82	     * @throws AccessDeniedException always
83	     */
84	    @ExceptionHandler(AccessDeniedException.class)
85	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
86	        throw e;
87	    }
88	
89	    /**
90	     * Handles a {@link RestRejectionException} raised by a controller when a business rule rejects a
91	     * request. The rejection is rendered as an RFC&nbsp;7807 {@code application/problem+json} body
92	     * carrying {@code type}, {@code title}, {@code status} and {@code detail}, preserving the
93	     * exception's HTTP status (a 400, 409 or 429).
94	     *
95	     * @param e The {@link RestRejectionException} to be handled
96	     * @param request {@link HttpServletRequest} object referring to the current request.
97	     * @return A {@link ResponseEntity} containing the problem detail and the rejection's HTTP status
98	     */
99	    @ExceptionHandler(RestRejectionException.class)
100	    @ResponseBody
101	    public ResponseEntity<ProblemDetail> handleRestRejectionException(RestRejectionException e, HttpServletRequest request) {
102	        HttpStatus status = e.getStatus();
103	        logger.debug("Request rejected at {} {} with status {}: {}",
104	            request.getMethod(),
105	            request.getRequestURI(),
106	            status.value(),
107	            e.getMessage());
108	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
109	        detail.setTitle(status.getReasonPhrase());
110	        return ResponseEntity.status(status).body(detail);
111	    }
112	
113	    /**
114	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
115	     *
116	     * @param e The {@link Exception} to be handled
117	     * @param request {@link HttpServletRequest} object referring to the current request.
118	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
119	     */
120	    @ExceptionHandler(Exception.class)
121	    @ResponseBody
122	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
123	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
124	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
125	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
126	        return ResponseEntity.status(status).body(detail);
127	    }
128	
129	    /**
130	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
131	     * method returns a 404 Not Found status if an entity does not exist.
132	     *
133	     * @param e The {@link DataIntegrityViolationException} to be handled
134	     * @param request {@link HttpServletRequest} object referring to the current request.
135	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
136	     */
137	    @ExceptionHandler(DataIntegrityViolationException.class)
138	    @ResponseBody
139	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
140	        logger.warn("Data integrity violation at {} {}: {}",
141	            request.getMethod(),
142	            request.getRequestURI(),
143	            e.getMessage());
144	        logger.debug("Data integrity violation stacktrace", e);
145	        HttpStatus status = HttpStatus.NOT_FOUND;
146	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
147	        return ResponseEntity.status(status).body(detail);
148	    }
149	
150	    /**
151	     * Handles exception thrown by Bean Validation on controller methods parameters
152	     *
153	     * @param e The {@link MethodArgumentNotValidException} to be handled
154	     * @param request {@link HttpServletRequest} object referring to the current request.
155	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
156	     */
157	    @ExceptionHandler(MethodArgumentNotValidException.class)
158	    @ResponseBody
159	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
160	        HttpStatus status = HttpStatus.BAD_REQUEST;
161	        BindingErrorsResponse errors = new BindingErrorsResponse();
162	        BindingResult bindingResult = e.getBindingResult();
163	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
164	        if (bindingResult.hasErrors()) {
165	            errors.addAllErrors(bindingResult);
166	            List<String> fieldNames = bindingResult.getFieldErrors().stream()
167	                .map(FieldError::getField)
168	                .distinct()
169	                .toList();
170	            detail.setProperty("errors", fieldNames);
171	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
172	                .map(fieldError -> {
173	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
174	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
175	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
176	                        fieldError.getField(),
177	                        defaultMessage,
178	                        rejectedValue);
179	                    return new ValidationMessageDto(message)
180	                        .putAdditionalProperty("field", fieldError.getField())
181	                        .putAdditionalProperty("rejectedValue", rejectedValue)
182	                        .putAdditionalProperty("defaultMessage", defaultMessage);
183	                })
184	                .toList();
185	            logger.debug("Validation error at {} {}: {}",
186	                request.getMethod(),
187	                request.getRequestURI(),
188	                bindingResult.getFieldErrors());
189	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
190	            return ResponseEntity.status(status).body(detail);
191	        }
192	        return ResponseEntity.status(status).body(detail);
193	    }
194	
195	}
