18	
19	import org.springframework.http.HttpStatus;
20	
21	/**
22	 * Signals that a request was rejected by a business rule and must be reported to the client with a
23	 * specific {@link HttpStatus} (a 400, 409 or 429). It is handled centrally by
24	 * {@link ExceptionControllerAdvice}, which renders every rejection as an RFC&nbsp;7807
25	 * {@code application/problem+json} body carrying {@code type}, {@code title}, {@code status} and
26	 * {@code detail}. Controllers throw this instead of returning a bodyless {@code ResponseEntity} so
27	 * that all rejection responses share one problem-detail representation.
28	 */
29	public class RestRejectionException extends RuntimeException {
30	
31	    private final HttpStatus status;
32	
33	    public RestRejectionException(HttpStatus status, String detail) {
34	        super(detail);
35	        this.status = status;
36	    }
37	
38	    public HttpStatus getStatus() {
39	        return this.status;
40	    }
41	}
