629	    /**
630	     * The owner's identity key: the single derived value used for duplicate detection. It is the
631	     * lower-case, 64-character hex SHA-256 digest over
632	     * {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName) + "|" + "V2"}, where
633	     * the telephone is the already-normalized stored value, the email is lower-cased (a {@code null}
634	     * email is rendered as the empty string), the last name is reduced to its Soundex code and
635	     * {@code "V2"} is the fixed {@link #IDENTITY_VERSION_TAG version tag} that rederives the key under
636	     * version 2 so it differs from every version-1 value. Two owners are duplicates only when their
637	     * whole identity keys are equal; because the telephone is part of the key, two owners sharing a
638	     * last name (Soundex) but with different telephones have different identity keys and so are not
639	     * hard duplicates.
640	     *
641	     * @return the derived identity key
642	     */
643	    public String getIdentityKey() {
644	        String telephonePart = this.telephone == null ? "" : this.telephone;
645	        String emailPart = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
646	        String soundexPart = soundex(getLastName());
647	        return sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart
648	            + "|" + IDENTITY_VERSION_TAG);
