651	    /**
652	     * Returns the lower-case, 64-character hex SHA-256 digest of the UTF-8 bytes of {@code input}.
653	     *
654	     * @param input the value to hash
655	     * @return the full hex digest
656	     */
657	    private static String sha256Hex(String input) {
658	        try {
659	            byte[] digest = MessageDigest.getInstance("SHA-256")
660	                .digest(input.getBytes(StandardCharsets.UTF_8));
661	            StringBuilder sb = new StringBuilder(digest.length * 2);
662	            for (byte b : digest) {
663	                sb.append(String.format("%02x", b));
664	            }
665	            return sb.toString();
666	        }
667	        catch (NoSuchAlgorithmException e) {
668	            throw new IllegalStateException("SHA-256 not available", e);
669	        }
670	    }
