672	    /**
673	     * Computes the American Soundex code of a name: the first letter followed by three digits that
674	     * phonetically encode the remaining consonants. Non-letters are ignored, {@code h} and {@code w}
675	     * are transparent (letters either side of them are treated as adjacent) and vowels reset the
676	     * run so a repeated code across a vowel is encoded twice. A {@code null} or letter-free value
677	     * yields the empty string.
678	     *
679	     * @param value the name to encode
680	     * @return the Soundex code, or the empty string when there is no letter to encode
681	     */
682	    public static String soundex(String value) {
683	        if (value == null) {
684	            return "";
685	        }
686	        StringBuilder letters = new StringBuilder();
687	        for (int i = 0; i < value.length(); i++) {
688	            char c = Character.toUpperCase(value.charAt(i));
689	            if (c >= 'A' && c <= 'Z') {
690	                letters.append(c);
691	            }
692	        }
693	        if (letters.length() == 0) {
694	            return "";
695	        }
696	        StringBuilder code = new StringBuilder();
697	        char first = letters.charAt(0);
698	        code.append(first);
699	        char last = soundexDigit(first);
700	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
701	            char c = letters.charAt(i);
702	            if (c == 'H' || c == 'W') {
703	                // Transparent: leave the previous code in place so letters either side stay adjacent.
704	                continue;
705	            }
706	            char digit = soundexDigit(c);
707	            if (digit != '0') {
708	                if (digit != last) {
709	                    code.append(digit);
710	                }
711	                last = digit;
712	            }
713	            else {
714	                // A vowel breaks the run so a following letter with the same code is encoded again.
715	                last = '0';
716	            }
717	        }
718	        while (code.length() < 4) {
719	            code.append('0');
720	        }
721	        return code.toString();
722	    }
