724	    /**
725	     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for vowels and the
726	     * uncoded letters {@code h} and {@code w}.
727	     */
728	    private static char soundexDigit(char c) {
729	        switch (c) {
730	            case 'B': case 'F': case 'P': case 'V':
731	                return '1';
732	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
733	                return '2';
734	            case 'D': case 'T':
735	                return '3';
736	            case 'L':
737	                return '4';
738	            case 'M': case 'N':
739	                return '5';
740	            case 'R':
741	                return '6';
742	            default:
743	                return '0';
744	        }
745	    }
