782	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
783	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
784	
785	    /**
786	     * The owner's timezone: the IANA name resolved from the {@link #getLocality() locality} via the
787	     * fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
788	     * {@code QLD->Australia/Brisbane}), or {@code null} when the locality is not one of these regions
789	     * (e.g. {@code "UNKNOWN"}).
790	     *
791	     * @return the IANA timezone name, or {@code null}
792	     */
793	    public String getTimezone() {
794	        return REGION_TIMEZONE.get(getLocality());
795	    }
796	
797	    /**
798	     * Region whose postcode range contains the given postcode, or {@code null} when the postcode is
799	     * absent, not a 4-digit number, or in no known range.
800	     *
801	     * @param postcode the owner's postcode (may be {@code null})
802	     * @return the matching region, or {@code null}
803	     */
804	    private static String regionForPostcode(String postcode) {
805	        if (postcode == null || !postcode.matches("\\d{4}")) {
806	            return null;
807	        }
808	        int value = Integer.parseInt(postcode);
809	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
810	            int[] range = entry.getValue();
811	            if (value >= range[0] && value <= range[1]) {
812	                return entry.getKey();
813	            }
814	        }
815	        return null;
816	    }
