21	import jakarta.persistence.EntityManager;
22	import jakarta.persistence.PersistenceContext;
23	import jakarta.persistence.Query;
24	
25	import org.jspecify.annotations.NonNull;
26	import org.springframework.context.annotation.Profile;
27	import org.springframework.dao.DataAccessException;
28	import org.springframework.data.domain.Page;
29	import org.springframework.data.domain.PageImpl;
30	import org.springframework.data.domain.Pageable;
